class AgentRecord(tuple):
    """Hybrid agent row supporting tuple, dict-style and attribute access."""

    _FIELDS = ("id", "codename", "status", "last_contact", "encrypted_message")

    def __new__(cls, id, codename, status, last_contact, encrypted_message):
        """Create an agent record from its five columns."""
        return super().__new__(
            cls, (id, codename, status, last_contact, encrypted_message)
        )

    def __getitem__(self, key):
        """Allow integer/slice access as a tuple and string access as a dict."""
        if isinstance(key, str):
            try:
                idx = self._FIELDS.index(key)
            except ValueError:
                raise KeyError(key)
            return super().__getitem__(idx)
        return super().__getitem__(key)

    def __getattr__(self, name):
        """Allow attribute access to the named columns."""
        if name in self._FIELDS:
            return self[self._FIELDS.index(name)]
        raise AttributeError(name)

    def get(self, key, default=None):
        """Return the column value for a dict-style key lookup."""
        try:
            return self[key]
        except (KeyError, IndexError, TypeError):
            return default

    def keys(self):
        """Return the column names."""
        return list(self._FIELDS)


class RendezvousResult(tuple):
    """Hybrid result acting as both an (lat, lon) tuple and formatted string."""

    def __new__(cls, lat, lon):
        """Create a rendezvous result from average latitude and longitude."""
        return super().__new__(cls, (float(lat), float(lon)))

    def __str__(self):
        """Return the formatted rendezvous string."""
        return f"Lat: {self[0]:.4f}, Lon: {self[1]:.4f}"

    def __repr__(self):
        """Return a developer-friendly representation."""
        return f"RendezvousResult(lat={self[0]!r}, lon={self[1]!r})"

    def __eq__(self, other):
        """Compare equal to tuples/lists (numeric) or formatted strings."""
        if isinstance(other, str):
            return str(self) == other
        if isinstance(other, (tuple, list)):
            try:
                if len(other) != 2:
                    return False
                return (
                    abs(float(other[0]) - float(self[0])) < 1e-6
                    and abs(float(other[1]) - float(self[1])) < 1e-6
                )
            except (TypeError, ValueError):
                return False
        return super().__eq__(other)


